namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly List<Notification> _notifications = [];

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(
        [
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile is complete."),
            CreateNotification("You have a new follower."),
        ]);
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        lock (_lock)
        {
            var newer = _notifications.Where(n => n.Timestamp > since).ToList();
            return Task.FromResult(newer);
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally by a hosted service or externally for testing.
    /// </summary>
    public void SimulateIncoming()
    {
        string[] messages =
        [
            "New comment on your post.",
            "Your build succeeded.",
            "A team member mentioned you.",
            "Deployment to production complete.",
            "New pull request review requested.",
            "Security alert resolved.",
        ];

        lock (_lock)
        {
            var msg = messages[Random.Shared.Next(messages.Length)];
            _notifications.Add(CreateNotification(msg));
        }
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

namespace BlazorApp.Services;

/// <summary>
/// Background service that adds a fake notification every 8 seconds
/// so the polling page has new data to discover.
/// </summary>
public class NotificationSimulator(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            notifications.SimulateIncoming();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationSvc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading notifications…</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? notifications;
    private DateTime lastChecked;
    private CancellationTokenSource? cts;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    [PersistentState]
    public DateTime PersistedLastChecked { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (PersistedNotifications is not null)
        {
            // Restored from prerender — skip the fetch.
            notifications = PersistedNotifications;
            lastChecked = PersistedLastChecked;
        }
        else
        {
            // First render (prerender): load from service.
            notifications = await NotificationSvc.GetNotificationsAsync();
            lastChecked = DateTime.UtcNow;

            // Persist so the interactive render can pick it up.
            PersistedNotifications = notifications;
            PersistedLastChecked = lastChecked;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender is NOT called during prerender,
            // so this only fires once the page is truly interactive.
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

            var newer = await NotificationSvc.GetNotificationsSinceAsync(lastChecked);

            if (newer.Count > 0)
            {
                notifications ??= [];
                notifications.AddRange(newer);
                lastChecked = DateTime.UtcNow;
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

