namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly List<Notification> _notifications = [];

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(
        [
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile is complete."),
            CreateNotification("You have a new follower."),
        ]);
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        lock (_lock)
        {
            var newer = _notifications.Where(n => n.Timestamp > since).ToList();
            return Task.FromResult(newer);
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// </summary>
    public void SimulateIncoming()
    {
        string[] messages =
        [
            "New comment on your post.",
            "Your build succeeded.",
            "A team member mentioned you.",
            "Deployment to production complete.",
            "New pull request review requested.",
            "Security alert resolved.",
        ];

        lock (_lock)
        {
            var msg = messages[Random.Shared.Next(messages.Length)];
            _notifications.Add(CreateNotification(msg));
        }
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

namespace BlazorApp.Services;

/// <summary>
/// Background service that adds a fake notification every 8 seconds
/// so the polling page has new data to discover.
/// </summary>
public class NotificationSimulator(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            notifications.SimulateIncoming();
        }
    }
}

